INSERT INTO sectors
(sector_code, sector_name, description)
VALUES
('ENER', 'Energy',
 'Companies engaged in the exploration, production, refining, marketing, storage, and transportation of oil, gas, coal, and consumable fuels. This sector also includes companies producing renewable energy and providing energy equipment and services.'),
('MATR', 'Materials',
  'Companies involved in the discovery, development, and processing of raw materials. This includes chemicals, construction materials, containers, packaging, metals, mining, and paper products.'),
('INDU', 'Industrials',
 'Companies that manufacture and distribute capital goods, provide commercial services, and transportation infrastructure. Includes aerospace, defense, building products, electrical equipment, industrial machinery, and transportation.'),
('COND', 'Consumer Discretionary',
 'Companies providing non-essential goods and services that consumers purchase with discretionary income. Includes personal transport, household durables, leisure products, media, retail, and hospitality.'),
('CONS', 'Consumer Staples',
 'Companies producing or selling essential consumer products including food, beverages, household items, and personal care products. Margins are influenced by commodity prices, brand strength, and distribution efficiency.'),
('HLTH', 'Healthcare',
 'Companies providing medical services, manufacturing healthcare equipment, and developing pharmaceuticals and biotechnology products. Includes healthcare providers, medical device manufacturers, and life sciences companies.'),
('FINL', 'Financials',
 'Companies providing financial services including banking, insurance, investment services, and real estate. This sector serves as the backbone of economic activity through capital allocation, risk transfer, and payment systems.'),
('UTIL', 'Utilities',
 'Companies providing essential public services including electric, gas, and water utilities. Characterized by regulated monopolies, stable cash flows, and high infrastructure investment requirements.'),
('REAL', 'Real Estate',
 'Companies engaged in the development, management, ownership, and leasing of real property. Includes real estate investment trusts (REITs), real estate developers, and real estate services.');
